SELECT id, code, name, label, category, jurisdiction, description, properties::text AS properties, create_time
FROM kg_node


        (name ILIKE CONCAT('%', #{keyword}, '%') OR description ILIKE CONCAT('%', #{keyword}, '%'))

    AND category = #{category}

ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE kg_node
name = #{name}, label = #{label}, category = #{category}, jurisdiction = #{jurisdiction}, description = #{description}, properties = CAST(#{properties} AS jsonb),
WHERE id = #{id}
